const customers = await api.peek("/customers", { status: "배송 지연" });
const mails = await api.peek("/mails", { label: "complaint" });
return { customers, mails };

const mails = await api.get("/mails", { label: "complaint" });
const customers = await api.get("/customers", { status: "배송 지연" });
return {
  mailCount: mails.count ?? mails.items?.length,
  mailCustomerIds: [...new Set((mails.items || []).map(m => m.customer_id))],
  customerItems: (customers.items || []).map(c => c.id ?? c),
  customerCount: customers.count,
};

const all = await api.get("/customers", {});
const items = all.items || [];
return { count: all.count, sample: items.slice(0, 3), statuses: [...new Set(items.map(c => c.status))] };

const all = await api.get("/customers", {});
const items = all.items || [];
const orderStatuses = items.map(c => ({ id: c.id, status: c.order?.status }));
const mails = await api.get("/mails", { label: "complaint" });
const complaintIds = [...new Set((mails.items || []).map(m => m.customer_id))];
return { orderStatuses, complaintIds };

